insert into public.faqs (id, question, answer, published, sort_order) values ('what-is-counselling', 'What is counselling?', 'Counselling is a supportive conversation with a trained counsellor in a private, non-judgmental space. It can help you make sense of what you are experiencing, reflect on your thoughts and feelings, and explore what you would like to move towards.', true, 0) on conflict (id) do nothing;
insert into public.faqs (id, question, answer, published, sort_order) values ('is-it-right-for-me', 'How do I know if counselling is right for me?', 'You do not need to have everything figured out, or to be in crisis, to benefit from counselling. If you feel you would value a space to pause, reflect, and be heard, counselling may be worth exploring. You are welcome to start a conversation with FUAD before deciding.', true, 1) on conflict (id) do nothing;
insert into public.faqs (id, question, answer, published, sort_order) values ('what-happens-in-a-session', 'What happens during a session?', 'Sessions are led at your pace. An early conversation usually focuses on understanding what brings you here. From there, you and your counsellor explore your experience together. There is no pressure to share more than you feel ready to.', true, 2) on conflict (id) do nothing;
insert into public.faqs (id, question, answer, published, sort_order) values ('how-to-choose-a-counsellor', 'How do I choose a counsellor?', 'You can read each counsellor’s profile to get a sense of who they are. If you are unsure, you are welcome to start a conversation with FUAD and we can help you consider what might suit you.', true, 3) on conflict (id) do nothing;
insert into public.faqs (id, question, answer, published, sort_order) values ('confidential', 'Are sessions confidential?', 'FUAD is designed as a space for thoughtful and private conversations. Details about confidentiality are shared with you as part of beginning counselling. If you have questions beforehand, you are welcome to ask.', true, 4) on conflict (id) do nothing;
insert into public.faqs (id, question, answer, published, sort_order) values ('how-do-i-start', 'How do I start?', 'You can start a conversation through our WhatsApp if you would like to ask something first. There is no pressure — you can begin at your own pace.', true, 5) on conflict (id) do nothing;
insert into public.faqs (id, question, answer, published, sort_order) values ('online-or-in-person', 'Are sessions online or in person?', 'Session format details are being confirmed. To find out the current options, please start a conversation with FUAD.', true, 6) on conflict (id) do nothing;
insert into public.faqs (id, question, answer, published, sort_order) values ('how-much', 'How much does counselling cost?', 'Pricing information is currently being updated. For current session details, please start a conversation with FUAD.', true, 7) on conflict (id) do nothing;
insert into public.faqs (id, question, answer, published, sort_order) values ('how-long', 'How long is a session?', 'Session length details are being confirmed and will be shared with you when you enquire or book.', true, 8) on conflict (id) do nothing;
insert into public.faqs (id, question, answer, published, sort_order) values ('contact-before-deciding', 'Can I contact FUAD before deciding?', 'Yes. You are welcome to start a conversation with FUAD on WhatsApp to ask questions before deciding whether counselling feels right for you.', true, 9) on conflict (id) do nothing;
insert into public.counsellors (slug, name, title, short_bio, full_bio, qualifications, certifications, experience, areas, specialties, languages, approach, session_format, fee, booking_url, photo, published, sort_order) values ('kanzah-mahar', 'Kanzah Mahar', '[TO BE CONFIRMED]', 'A counsellor at FUAD, offering a warm and non-judgmental space to be heard.', 'Kanzah is part of the FUAD counselling team. Further details about background, approach, and areas of support are being confirmed and will be added here.', ARRAY['[TO BE CONFIRMED]']::text[], ARRAY['[TO BE CONFIRMED]']::text[], '[TO BE CONFIRMED]', ARRAY['[TO BE CONFIRMED]']::text[], ARRAY['[TO BE CONFIRMED]']::text[], ARRAY['[TO BE CONFIRMED]']::text[], '[TO BE CONFIRMED]', '[TO BE CONFIRMED]', '[TO BE CONFIRMED]', null, '/counsellor-placeholder.png', true, 0) on conflict (slug) do nothing;
insert into public.counsellors (slug, name, title, short_bio, full_bio, qualifications, certifications, experience, areas, specialties, languages, approach, session_format, fee, booking_url, photo, published, sort_order) values ('adeel-hanif', 'Adeel Hanif', '[TO BE CONFIRMED]', 'A counsellor at FUAD, providing thoughtful and respectful support.', 'Adeel is part of the FUAD counselling team. Further details about background, approach, and areas of support are being confirmed and will be added here.', ARRAY['[TO BE CONFIRMED]']::text[], ARRAY['[TO BE CONFIRMED]']::text[], '[TO BE CONFIRMED]', ARRAY['[TO BE CONFIRMED]']::text[], ARRAY['[TO BE CONFIRMED]']::text[], ARRAY['[TO BE CONFIRMED]']::text[], '[TO BE CONFIRMED]', '[TO BE CONFIRMED]', '[TO BE CONFIRMED]', null, '/counsellor-placeholder.png', true, 1) on conflict (slug) do nothing;
insert into public.counsellors (slug, name, title, short_bio, full_bio, qualifications, certifications, experience, areas, specialties, languages, approach, session_format, fee, booking_url, photo, published, sort_order) values ('maham-binte-amar', 'Maham Binte Amar', '[TO BE CONFIRMED]', 'A counsellor at FUAD, offering a calm space for reflection and growth.', 'Maham is part of the FUAD counselling team. Further details about background, approach, and areas of support are being confirmed and will be added here.', ARRAY['[TO BE CONFIRMED]']::text[], ARRAY['[TO BE CONFIRMED]']::text[], '[TO BE CONFIRMED]', ARRAY['[TO BE CONFIRMED]']::text[], ARRAY['[TO BE CONFIRMED]']::text[], ARRAY['[TO BE CONFIRMED]']::text[], '[TO BE CONFIRMED]', '[TO BE CONFIRMED]', '[TO BE CONFIRMED]', null, '/counsellor-placeholder.png', true, 2) on conflict (slug) do nothing;
insert into public.services (slug, title, summary, intro, supports, concerns, involves, expect, related, counsellors, booking_url, published, sort_order) values ('individual-counselling', 'Individual Counselling', 'One-to-one support to slow down, make sense of what you are feeling, and explore what comes next.', 'Individual counselling offers a private space to talk openly about what is on your mind. Together with a counsellor, you can explore your thoughts and feelings, notice patterns, and consider gentle, realistic steps forward — at a pace that feels right for you.', ARRAY['Anyone feeling overwhelmed, stuck, or unsure where to begin', 'People navigating a difficult period or life transition', 'Those who simply want a space to reflect and be heard']::text[], ARRAY['Low mood or persistent worry', 'Feeling disconnected or unmotivated', 'Difficulty coping with change', 'Questions about identity, purpose, or direction']::text[], ARRAY['An initial conversation to understand what brings you here', 'A collaborative, non-judgmental space to explore your experience', 'Gentle reflection on thoughts, feelings, and patterns']::text[], ARRAY['To be listened to with care and without judgment', 'To move at a pace that feels comfortable', 'To take an active role in your own growth']::text[], ARRAY['anxiety-and-stress', 'personal-growth', 'trauma-support']::text[], ARRAY['kanzah-mahar', 'adeel-hanif', 'maham-binte-amar']::text[], null, true, 0) on conflict (slug) do nothing;
insert into public.services (slug, title, summary, intro, supports, concerns, involves, expect, related, counsellors, booking_url, published, sort_order) values ('marriage-counselling', 'Marriage Counselling', 'A supportive space for couples to understand each other more clearly and communicate with care.', 'Marriage counselling provides a space where both partners can speak honestly and feel heard. It can help you understand recurring patterns, ease difficult conversations, and explore healthier ways of relating to one another.', ARRAY['Couples wanting to communicate more openly', 'Partners navigating tension or distance', 'Those working through a significant change together']::text[], ARRAY['Recurring conflict or misunderstandings', 'Feeling unheard or disconnected', 'Adjusting to new responsibilities or life stages']::text[], ARRAY['A shared space where both perspectives matter', 'Support in understanding patterns of communication', 'Exploring ways to reconnect and move forward']::text[], ARRAY['A balanced, respectful environment for both partners', 'No taking of sides', 'A focus on understanding rather than blame']::text[], ARRAY['relationship-counselling', 'individual-counselling']::text[], ARRAY['adeel-hanif', 'kanzah-mahar']::text[], null, true, 1) on conflict (slug) do nothing;
insert into public.services (slug, title, summary, intro, supports, concerns, involves, expect, related, counsellors, booking_url, published, sort_order) values ('relationship-counselling', 'Relationship Counselling', 'Support for the relationships that matter to you — family, partners, and close connections.', 'Our relationships shape much of how we feel day to day. Relationship counselling offers space to explore the connections that matter to you, understand what feels difficult, and consider how you would like things to be.', ARRAY['Anyone finding a relationship difficult to navigate', 'People wanting to understand their own patterns', 'Those adjusting to changing family dynamics']::text[], ARRAY['Difficulty setting or holding boundaries', 'Feeling misunderstood by those close to you', 'Navigating family expectations']::text[], ARRAY['Exploring the relationships and roles in your life', 'Understanding communication and expectations', 'Considering healthier, sustainable responses']::text[], ARRAY['A space to speak honestly about what feels hard', 'Reflection without judgment', 'A pace that respects your comfort']::text[], ARRAY['marriage-counselling', 'individual-counselling', 'parenting-support']::text[], ARRAY['kanzah-mahar', 'maham-binte-amar']::text[], null, true, 2) on conflict (slug) do nothing;
insert into public.services (slug, title, summary, intro, supports, concerns, involves, expect, related, counsellors, booking_url, published, sort_order) values ('anxiety-and-stress', 'Anxiety & Stress', 'A calm space to understand anxiety and stress and explore ways to respond to them.', 'Anxiety and stress can affect how we think, feel, and move through daily life. Counselling can help you understand what you are experiencing, notice what tends to trigger it, and explore gentle ways of responding.', ARRAY['People feeling persistently worried or on edge', 'Those experiencing pressure that feels hard to carry', 'Anyone wanting to understand their stress responses']::text[], ARRAY['Racing thoughts or difficulty switching off', 'Feeling overwhelmed by daily demands', 'Physical tension linked to stress']::text[], ARRAY['Understanding your experience of anxiety or stress', 'Noticing patterns and triggers', 'Exploring healthier responses over time']::text[], ARRAY['A calm, unhurried space', 'No pressure to have the right words', 'Support tailored to your experience']::text[], ARRAY['individual-counselling', 'work-pressure', 'trauma-support']::text[], ARRAY['maham-binte-amar', 'kanzah-mahar']::text[], null, true, 3) on conflict (slug) do nothing;
insert into public.services (slug, title, summary, intro, supports, concerns, involves, expect, related, counsellors, booking_url, published, sort_order) values ('trauma-support', 'Trauma Support', 'Careful, paced support for those working through difficult past experiences.', 'Difficult experiences can stay with us in ways that are not always easy to put into words. Trauma support offers a careful, paced space to be heard and supported, with respect for your comfort and your sense of safety throughout.', ARRAY['People carrying the weight of past experiences', 'Those who feel affected by something difficult', 'Anyone wanting a safe, paced space to talk']::text[], ARRAY['Feeling affected by past events', 'Difficulty feeling settled or safe', 'Wanting support at a careful pace']::text[], ARRAY['A gentle, paced approach led by your comfort', 'A focus on safety and trust', 'Space to be heard without pressure']::text[], ARRAY['Respect for your pace and boundaries', 'A steady, supportive presence', 'No pressure to share more than you wish']::text[], ARRAY['individual-counselling', 'anxiety-and-stress']::text[], ARRAY['kanzah-mahar', 'adeel-hanif']::text[], null, true, 4) on conflict (slug) do nothing;
insert into public.services (slug, title, summary, intro, supports, concerns, involves, expect, related, counsellors, booking_url, published, sort_order) values ('parenting-support', 'Parenting Support', 'Thoughtful support for the questions and pressures that come with parenting.', 'Parenting brings meaning and joy, and it can also bring pressure, doubt, and exhaustion. Parenting support offers a space to reflect on the challenges you are facing and explore approaches that feel right for you and your family.', ARRAY['Parents feeling stretched or unsure', 'Those navigating a difficult stage with a child', 'Anyone wanting space to reflect on parenting']::text[], ARRAY['Feeling overwhelmed by responsibilities', 'Navigating difficult behaviour or transitions', 'Balancing parenting with everything else']::text[], ARRAY['Space to talk through what feels difficult', 'Reflection on patterns and pressures', 'Exploring approaches that suit your family']::text[], ARRAY['A non-judgmental space', 'Respect for your values and circumstances', 'Support rather than instruction']::text[], ARRAY['relationship-counselling', 'individual-counselling']::text[], ARRAY['maham-binte-amar', 'kanzah-mahar']::text[], null, true, 5) on conflict (slug) do nothing;
insert into public.services (slug, title, summary, intro, supports, concerns, involves, expect, related, counsellors, booking_url, published, sort_order) values ('work-pressure', 'Work Pressure', 'Support for navigating stress, burnout, and the demands of working life.', 'Work can be a source of purpose and also a source of significant pressure. Counselling can offer space to understand how work is affecting you, explore what feels unsustainable, and consider healthier ways of coping.', ARRAY['People feeling burnt out or overextended', 'Those struggling with work-life balance', 'Anyone carrying ongoing pressure from work']::text[], ARRAY['Exhaustion or difficulty switching off', 'Pressure that feels hard to sustain', 'Difficulty setting boundaries at work']::text[], ARRAY['Understanding how work is affecting you', 'Exploring boundaries and expectations', 'Considering healthier, sustainable responses']::text[], ARRAY['A space that takes your pressures seriously', 'No judgment about how you are coping', 'Support tailored to your situation']::text[], ARRAY['anxiety-and-stress', 'personal-growth', 'individual-counselling']::text[], ARRAY['adeel-hanif', 'maham-binte-amar']::text[], null, true, 6) on conflict (slug) do nothing;
insert into public.services (slug, title, summary, intro, supports, concerns, involves, expect, related, counsellors, booking_url, published, sort_order) values ('personal-growth', 'Personal Growth / Mentorship', 'A reflective space for those who want to understand themselves and grow with intention.', 'Personal growth is not only for difficult times. This space is for anyone who wants to understand themselves more deeply, reflect on where they are, and move towards where they would like to be — with support and intention.', ARRAY['People wanting to understand themselves better', 'Those reflecting on direction and purpose', 'Anyone seeking growth with support']::text[], ARRAY['A sense of feeling stuck or uncertain', 'Wanting clarity on values and direction', 'A desire to grow with intention']::text[], ARRAY['Reflective conversation about your goals', 'Exploring values, patterns, and direction', 'Considering meaningful, realistic steps']::text[], ARRAY['A collaborative, forward-looking space', 'Respect for your own pace and choices', 'Support in taking an active role in your growth']::text[], ARRAY['individual-counselling', 'work-pressure']::text[], ARRAY['adeel-hanif', 'kanzah-mahar', 'maham-binte-amar']::text[], null, true, 7) on conflict (slug) do nothing;
